-- Vcare migration data, generated 2026-09-23T14:56:35.135Z from the
-- development database by scratch/vcare-gen-migration.mjs.
--
-- Carries the staff logins, role definitions, job attribution and
-- installation challans that could not be scripted against production,
-- because its connection string is a write-only Vercel Sensitive variable.
--
-- Every statement is guarded, so this is a no-op on a database that already
-- has the data - including the development database it was generated from.
-- No id is hard-coded: the store resolves by organisation name, and users,
-- roles, complaints and products resolve by their natural keys.

-- 6 roles -------------------------------------------------
INSERT INTO "Role" (id, "storeId", name, description, level, "designationCode")
SELECT gen_random_uuid()::text, (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), r.name, r.descr, r.lvl, r.code
FROM (VALUES
  ('HOD', 'Migrated from Vcare role "hod"', 2, 'HOD'),
  ('Senior Manager', 'Migrated from Vcare role "senior_manager"', 2, 'SRMGR'),
  ('Manager', 'Migrated from Vcare role "manager"', 3, 'MGR'),
  ('Head Technician', 'Migrated from Vcare role "head_technician"', 4, 'HTECH'),
  ('Technician', 'Migrated from Vcare role "technician"', 5, 'TECH'),
  ('Helper', 'Migrated from Vcare role "helper"', 6, 'HELP')
) AS r(name, descr, lvl, code)
WHERE NOT EXISTS (SELECT 1 FROM "Role" x WHERE x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND x.name = r.name);

