-- 26 staff logins ------------------------------------------
-- The password hash is scrypt, one-way, and identical to what the database
-- already stores - so the credential sheet already issued keeps working.
-- userCode is derived from the username so it is stable across databases
-- rather than carried over and risking a collision.
INSERT INTO "User" (id, "userCode", "organizationId", "fullName", username, email, phone, "passwordHash", "isSeatLicensed", "isActive", "updatedAt")
