-- 27 role assignments ----------------------------------------
INSERT INTO "UserStoreRole" ("userId", "storeId", "roleId")
SELECT us.id, (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), ro.id
FROM (VALUES
  ('amit.nale', 'Technician'),
  ('bhupendra.nirmalkar', 'Helper'),
  ('chandraprakash.nirmalkar', 'Technician'),
  ('devendra.yadav', 'Helper'),
  ('harsh.nirmalkar', 'Technician'),
  ('harsh.yadav', 'Helper'),
  ('hema.dewangan', 'Manager'),
  ('jeevan.mandavi', 'Technician'),
  ('keshar.sen', 'Manager'),
  ('lav.kumar', 'Technician'),
  ('mayank.thakur', 'Technician'),
  ('nagesh.thakur', 'Technician'),
  ('nandkishor.yadav', 'Helper'),
  ('nishan.singh', 'Technician'),
  ('nishanjeet.singh', 'Manager'),
  ('paramjeet.singh', 'Technician'),
  ('prachi.dewangan', 'Manager'),
  ('raj.khare', 'Technician'),
  ('rupesh.sahu', 'Helper'),
  ('sahil.sahu', 'Technician'),
  ('sangeet.mahobia', 'Senior Manager'),
  ('sunita.sahu', 'Manager'),
  ('surya.yadav', 'Technician'),
  ('tikam.sahu', 'Head Technician'),
  ('usha.yadav', 'Manager'),
  ('vcareglobal', 'Admin'),
  ('vikash.deshlahra', 'Technician')
) AS m(uname, rname)
JOIN "User" us ON us.username = m.uname
JOIN "Role" ro ON ro."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND ro.name = m.rname
WHERE NOT EXISTS (SELECT 1 FROM "UserStoreRole" x
  WHERE x."userId" = us.id AND x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND x."roleId" = ro.id);

