     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c."complaintNo" = m.cno
  AND c."assignedTechnicianId" IS NULL;

-- 203 installation challans ---------------------------------
-- The terms text is one of only 2 values across all 203 rows, so it is
-- emitted once and referenced by index rather than repeated (saves ~75 KB).
INSERT INTO "InstallationChallan"
  (id, "storeId", "challanNo", "legacyRef", "salesOrderId", status,
   "physicalChallanNo", "technicianRemark", "termsBody",
   "dispatchedAt", "completedAt", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), c.cno, c.lref,
       (SELECT so.id FROM "SalesOrder" so WHERE so."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND so."orderNo" = c.ono),
       c.status, c.slip, c.remark, t.body,
       c.disp, c.compl, c.crea, now()
FROM (VALUES
  (0, '1.Warranty on all Products applicable as per Company rules. We are only Traders.
                2.Payment to be made as per terms of payment slipulated in the invoice other wise interest will be charged @ 2% per month.
                3.We are not responsible for any service/ repaired material/ Product after 7 days from day of intimation to client for pickup or installation.'),
  (1, 'Dummy')
) AS t(idx, body)
