WHERE NOT EXISTS (SELECT 1 FROM "InstallationChallan" x
  WHERE x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND x."challanNo" = c.cno);

-- 1105 line items. Product resolves by productCode, not by id.
